const ERR_NOT_ADMIN = 401;
const ERR_NOT_OWNER = 402;
const ERR_NOT_MASTER = 403;
const ERR_NOT_ALLOWED = 404;
const ERR_INSUFFICIENT_BALANCE = 405;
const ERR_MINTING_DISABLED = 406;
const ERR_PAUSED = 407;
const ERR_INVALID_SENDER_WALLET = 408;
const ERR_NOT_ENOUGH_TON = 409;
const ERR_NOT_TREASURY = 410;
const ERR_WRONG_WORKCHAIN = 333;
const ERR_UNKNOWN_OP = 0xffff;

tolk 1.4.1

// ---- Standard TEP-74 messages ----

struct (0x0f8a7ea5) JettonTransfer {
    queryId: uint64;
    jettonAmount: coins;
    transferRecipient: address;     // destination owner
    sendExcessesTo: address;        // response_destination
    customPayload: cell?;           // (Maybe ^Cell)
    forwardTonAmount: coins;
    forwardPayload: RemainingBitsAndRefs;   // (Either Cell ^Cell)
}

struct (0x178d4519) InternalTransferStep {
    queryId: uint64;
    jettonAmount: coins;
    transferInitiator: address;     // 'from' owner (minter address for mints)
    sendExcessesTo: address;        // response_destination
    forwardTonAmount: coins;
    forwardPayload: RemainingBitsAndRefs;
}

struct (0x7362d09c) TransferNotificationForRecipient {
    queryId: uint64;
    jettonAmount: coins;
    transferInitiator: address;     // 'sender'
    forwardPayload: RemainingBitsAndRefs;
}

struct (0xd53276db) ReturnExcessesBack {
    queryId: uint64;
}

struct (0x595f07bc) JettonBurn {
    queryId: uint64;
    jettonAmount: coins;
    sendExcessesTo: address;        // response_destination
    customPayload: cell?;
}

struct (0x7bdd97de) BurnNotificationForMinter {
    queryId: uint64;
    jettonAmount: coins;
    burnInitiator: address;         // 'sender' owner
    sendExcessesTo: address;        // response_destination
}

// ---- Custom permissioning / admin messages ----

struct (0x74630001) MintRequest {
    queryId: uint64;
    toOwner: address;
    jettonAmount: coins;
    forwardTonAmount: coins;
}

struct (0x74630002) ActivateWallet {
    queryId: uint64;
    ownerAddress: address;
}

struct (0x74630003) BlockWallet {
    queryId: uint64;
    ownerAddress: address;
}

struct (0x74630004) SetWalletStatus {
    queryId: uint64;
    newStatus: uint8;
}

struct (0x74630005) ChangeAdmin {
    queryId: uint64;
    newAdmin: address;
}

struct (0x74630006) ChangeContent {
    queryId: uint64;
    newContent: cell;
}

struct (0x74630007) SetMintingEnabled {
    queryId: uint64;
    enabled: bool;
}

struct (0x74630008) SetGlobalPause {
    queryId: uint64;
    isPaused: bool;
}

struct (0x74630009) ChangeTreasuryOwner {
    queryId: uint64;
    newTreasuryOwner: address;
}

tolk 1.4.1

import "constants.tolk"

struct WalletStorage {
    status: uint8;
    jettonBalance: coins;
    ownerAddress: address;
    minterAddress: address;
}

fun WalletStorage.load(): WalletStorage {
    return WalletStorage.fromCell(contract.getData());
}

fun WalletStorage.save(self): void {
    contract.setData(self.toCell());
}

// Canonical wallet for an owner. Status is ALWAYS STATUS_BLOCKED in the
// address-determining template, so a self-deployed wallet is born blocked.
fun calcDeployedJettonWallet(ownerAddress: address, minterAddress: address, walletCode: cell): AutoDeployAddress {
    val initialData: WalletStorage = {
        status: STATUS_BLOCKED,
        jettonBalance: 0,
        ownerAddress: ownerAddress,
        minterAddress: minterAddress,
    };
    return {
        workchain: BASECHAIN,
        stateInit: { code: walletCode, data: initialData.toCell() },
    };
}
